// Verifies the HMAC signature Convex puts on every request event and
// drops events this workflow has already handled.
// Signed string: `${timestamp}.POST /request-events.${rawBody}`
// Same scheme as convex/lib/signature.ts.
const crypto = require('crypto');

const SECRET = $env.LENDLOOP_CONVEX_TO_N8N_SECRET;
const ROUTE = 'POST /request-events';
const TOLERANCE_SECONDS = 300;

const headers = $json.headers || {};
const signature = String(headers['x-lendloop-signature'] || '');
const timestamp = String(headers['x-lendloop-timestamp'] || '');

// Prefer the raw bytes (Webhook node "Raw Body" option). Convex sends
// compact JSON, so re-serialising the parsed body is an exact fallback.
let rawBody = JSON.stringify($json.body);
const raw = $input.item.binary && $input.item.binary.data;
if (raw && raw.data && raw.data !== 'filesystem-v2') {
  rawBody = Buffer.from(raw.data, 'base64').toString('utf8');
}

const reject = (reason) => ({ json: { status: 'invalid', reason } });

if (!SECRET) return reject('NOT_CONFIGURED');
if (!/^\d{1,12}$/.test(timestamp)) return reject('INVALID_TIMESTAMP');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > TOLERANCE_SECONDS) {
  return reject('TIMESTAMP_OUT_OF_RANGE');
}

const expected =
  'v1=' +
  crypto
    .createHmac('sha256', SECRET)
    .update(`${timestamp}.${ROUTE}.${rawBody}`)
    .digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return reject('INVALID_SIGNATURE');
}

const event = JSON.parse(rawBody);
const processed = $getWorkflowStaticData('global').processedEvents || {};
if (processed[event.eventId]) {
  return { json: { status: 'duplicate', eventId: event.eventId } };
}
return { json: { status: 'ok', event } };

// Builds the notification from the minimal event payload. Nothing here
// needs more than first name, email, tool name and dates.
const { event } = $json;
const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const { firstName } = event.recipient;
const tool = event.tool.name;
const dates = event.dates.start === event.dates.end
  ? event.dates.start
  : `${event.dates.start} to ${event.dates.end}`;

const copy = {
  'loan.requested': [
    `New request for your ${tool}`,
    `Hi ${firstName}, a neighbour would like to borrow your ${tool} (${dates}). Approve or decline: ${appUrl}/incoming`,
  ],
  'loan.cancelled': [
    `Request for your ${tool} was cancelled`,
    `Hi ${firstName}, the request to borrow your ${tool} (${dates}) was cancelled. Nothing to do.`,
  ],
  'loan.approved': [
    `Approved: ${tool}`,
    `Hi ${firstName}, your request to borrow the ${tool} (${dates}) was approved. Details: ${appUrl}/my-requests`,
  ],
  'loan.declined': [
    `Request declined: ${tool}`,
    `Hi ${firstName}, your request to borrow the ${tool} (${dates}) was declined. Have a look for another on the board: ${appUrl}/tools`,
  ],
  'loan.returned': [
    `Thanks for returning the ${tool}`,
    `Hi ${firstName}, the ${tool} has been marked as returned. Thanks for looking after it.`,
  ],
};

const message = copy[event.type];
if (!message) throw new Error(`Unknown event type: ${event.type}`);

return {
  json: {
    eventId: event.eventId,
    type: event.type,
    to: event.recipient.email,
    subject: message[0],
    text: message[1],
  },
};

// Mock channel: logs the notification instead of sending it. The email
// address is masked so the n8n log never holds full PII.
const masked = $json.to.replace(/^(.).*(@.*)$/, '$1***$2');
console.log(`[lendloop] ${$json.type} -> ${masked}: ${$json.subject}`);
return { json: { eventId: $json.eventId, channel: 'mock', to: masked } };

// Only now is the event marked as handled, so a failed send is retried
// by Convex (same eventId) instead of being swallowed as a duplicate.
const eventId = $('Build message').item.json.eventId;
const data = $getWorkflowStaticData('global');
const processed = data.processedEvents || {};
const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
for (const [key, at] of Object.entries(processed)) {
  if (at < weekAgo) delete processed[key];
}
processed[eventId] = Date.now();
data.processedEvents = processed;
return { json: { ok: true, eventId } };
